@extends('admin.layouts.app',['title'=>'Profile','heading'=>'Profile']) @section('content')<x-pulse.page-header title="Profile and sessions" description="Manage your identity, credentials, and signed-in devices."/><x-pulse.errors/><x-pulse.card><h2>Profile</h2><form method="POST" action="{{ route('admin.profile.update') }}" class="p-form">@csrf @method('PATCH')<x-pulse.field name="name" label="Name" :value="auth()->user()->name" required maxlength="255"/><x-pulse.field name="email" label="Email address" type="email" :value="auth()->user()->email" required/><x-pulse.button type="submit">Save profile</x-pulse.button></form></x-pulse.card><x-pulse.card><h2>Password</h2><p class="p-help">Password changes require recent confirmation.</p><form method="POST" action="{{ route('admin.profile.password') }}" class="p-form">@csrf @method('PUT')<x-pulse.field name="password" label="New password" type="password" required autocomplete="new-password"/><x-pulse.field name="password_confirmation" label="Confirm new password" type="password" required autocomplete="new-password"/><x-pulse.button type="submit">Change password</x-pulse.button></form></x-pulse.card><x-pulse.card><h2>Sessions</h2>@if(config('session.driver')!=='database')<x-pulse.alert variant="info">Session visibility is unavailable with the configured {{ config('session.driver') }} session driver.</x-pulse.alert>@elseif($sessions->isEmpty())<x-pulse.empty title="No persisted sessions found">Your current session may use a different session driver.</x-pulse.empty>@else<ul>@foreach($sessions as $session)<li><strong>{{ $session->ip_address?:'Unknown IP' }}</strong> · {{ $session->user_agent?\Illuminate\Support\Str::limit($session->user_agent,100):'Unknown browser' }} · {{ \Illuminate\Support\Carbon::createFromTimestamp($session->last_activity)->diffForHumans() }}<form method="POST" action="{{ route('admin.profile.sessions.destroy',$session->id) }}">@csrf @method('DELETE')<x-pulse.button variant="danger" data-confirm data-con